// src/components/SvgFlow.js
import React, { useEffect, useRef } from "react";
import * as d3 from "d3";
import "../components/SvgFlow.css";

function SvgFlow({ graph }) {
  const svgRef = useRef();

  useEffect(() => {
    if (!graph) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove(); // clear old diagram

    const width = 900;
    const height = 600;
    svg.attr("width", width).attr("height", height);

    const nodeWidth = 160;
    const nodeHeight = 50;
    const verticalGap = 80;

    // Layout
    graph.nodes.forEach((n, i) => {
      n.x = width / 2;
      n.y = 80 + i * verticalGap;
    });

    // Draw edges (arrows)
    svg
      .append("defs")
      .append("marker")
      .attr("id", "arrow")
      .attr("viewBox", "0 0 10 10")
      .attr("refX", 10)
      .attr("refY", 5)
      .attr("markerWidth", 6)
      .attr("markerHeight", 6)
      .attr("orient", "auto-start-reverse")
      .append("path")
      .attr("d", "M 0 0 L 10 5 L 0 10 z")
      .attr("fill", "white");

    graph.edges.forEach(edge => {
      const from = graph.nodes.find(n => n.id === edge.from);
      const to = graph.nodes.find(n => n.id === edge.to);

      if (!from || !to) return;

      svg
        .append("line")
        .attr("x1", from.x)
        .attr("y1", from.y + nodeHeight / 2)
        .attr("x2", to.x)
        .attr("y2", to.y - nodeHeight / 2)
        .attr("stroke", "#fff")
        .attr("stroke-width", 2)
        .attr("marker-end", "url(#arrow)");

      if (edge.label) {
        svg
          .append("text")
          .attr("x", (from.x + to.x) / 2 + 10)
          .attr("y", (from.y + to.y) / 2)
          .attr("fill", "white")
          .attr("font-size", "11px")
          .text(edge.label);
      }
    });

    // Node shapes
    const nodeGroup = svg
      .selectAll(".node")
      .data(graph.nodes)
      .enter()
      .append("g")
      .attr("transform", d => `translate(${d.x - nodeWidth / 2}, ${d.y - nodeHeight / 2})`);

    nodeGroup.each(function (d) {
      const g = d3.select(this);
      if (d.type === "decision") {
        // Diamond for if/else
        const size = 50;
        g.append("polygon")
          .attr(
            "points",
            `${nodeWidth / 2},0 ${nodeWidth},${nodeHeight / 2} ${nodeWidth / 2},${nodeHeight} 0,${nodeHeight / 2}`
          )
          .attr("fill", "#9333ea");
      } else if (d.type === "loop") {
        // Hexagon for loops
        const w = nodeWidth, h = nodeHeight;
        g.append("polygon")
          .attr(
            "points",
            `20,0 ${w - 20},0 ${w},${h / 2} ${w - 20},${h} 20,${h} 0,${h / 2}`
          )
          .attr("fill", "#2563eb");
      } else if (d.type === "return" || d.type === "function") {
        // Oval
        g.append("ellipse")
          .attr("cx", nodeWidth / 2)
          .attr("cy", nodeHeight / 2)
          .attr("rx", nodeWidth / 2)
          .attr("ry", nodeHeight / 2.5)
          .attr("fill", "#059669");
      } else {
        // Normal rectangle
        g.append("rect")
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", 10)
          .attr("fill", "#6d28d9");
      }
    });

    nodeGroup
      .append("text")
      .attr("x", nodeWidth / 2)
      .attr("y", nodeHeight / 2)
      .attr("text-anchor", "middle")
      .attr("alignment-baseline", "middle")
      .attr("fill", "white")
      .attr("font-size", "11px")
      .text(d => d.text.length > 40 ? d.text.slice(0, 40) + "..." : d.text);
  }, [graph]);

  return (
    <div style={{ background: "#111", padding: "20px", borderRadius: "12px" }}>
      <svg ref={svgRef}></svg>
    </div>
  );
}

export default SvgFlow;
